      (SyscallNo (37)) -> SyscallTraceBody_get_storage_flags <$> cxsGet
      (SyscallNo (38)) -> SyscallTraceBody_clear_storage_flags <$> cxsGet
      _ -> pure (SyscallTraceBody_default d))

