data HostFunctionStatusXdr
  = HostFunctionStatusXdr_syscall_return_code SyscallErrorCode
  | HostFunctionStatusXdr_default HostFnErrorCode
  deriving (Eq, Ord, Show)

instance XdrType HostFunctionStatusXdr where
  xdrPut (HostFunctionStatusXdr_syscall_return_code v) = xdrPut (HostFnErrorCode (0)) <> xdrPut v
  xdrPut (HostFunctionStatusXdr_default d)
    | d `notElem` [(HostFnErrorCode (0))] = xdrPut d
    | otherwise = error "bad discriminant for HostFunctionStatusXdr_default"
  xdrGet = do
    d <- xdrGet
    case d of
      (HostFnErrorCode (0)) -> HostFunctionStatusXdr_syscall_return_code <$> xdrGet
      _ -> pure (HostFunctionStatusXdr_default d)
  cxsPut (HostFunctionStatusXdr_syscall_return_code v) = cxsPut (HostFnErrorCode (0)) <> cxsPut v
  cxsPut (HostFunctionStatusXdr_default d)
    | d `notElem` [(HostFnErrorCode (0))] = cxsPut d
    | otherwise = error "bad discriminant for HostFunctionStatusXdr_default"
  cxsGet = do
    d <- cxsGet
    case d of
      (HostFnErrorCode (0)) -> HostFunctionStatusXdr_syscall_return_code <$> cxsGet
      _ -> pure (HostFunctionStatusXdr_default d)

-- | The discriminant of a 'HostFunctionStatusXdr'.
discriminant_HostFunctionStatusXdr :: HostFunctionStatusXdr -> HostFnErrorCode
discriminant_HostFunctionStatusXdr (HostFunctionStatusXdr_syscall_return_code _) = (HostFnErrorCode (0))
discriminant_HostFunctionStatusXdr (HostFunctionStatusXdr_default d) = d

xdrMin_HostFunctionStatusXdr, xdrMax_HostFunctionStatusXdr :: Integer
xdrMin_HostFunctionStatusXdr = 4
xdrMax_HostFunctionStatusXdr = 8

data SyscallTrace = SyscallTrace
  { gas_remaining_at_start :: GasAmount
  , gas_remaining_at_end :: GasAmount
  , body :: SyscallTraceBody
  , status :: HostFunctionStatusXdr
  }
  deriving (Eq, Ord, Show)

instance XdrType SyscallTrace where
  xdrPut (SyscallTrace x1 x2 x3 x4) = put_GasAmount x1 <> put_GasAmount x2 <> xdrPut x3 <> xdrPut x4
  xdrGet = getRecursive (SyscallTrace <$> get_GasAmount <*> get_GasAmount <*> xdrGet <*> xdrGet)
  cxsPut (SyscallTrace x1 x2 x3 x4) = cxsPut_GasAmount x1 <> cxsPut_GasAmount x2 <> cxsPut x3 <> cxsPut x4
  cxsGet = getRecursive (SyscallTrace <$> cxsGet_GasAmount <*> cxsGet_GasAmount <*> cxsGet <*> cxsGet)

data InvocationFrameTrace = InvocationFrameTrace
  { invocation :: Invocation
  , system_calls :: [SyscallTrace]
  , storage_writes :: [FlaggedStorageDelta]
  , status :: InvocationFrameOutput
  , commit_conflict :: DbConflictResult
  }
  deriving (Eq, Ord, Show)

instance XdrType InvocationFrameTrace where
  xdrPut (InvocationFrameTrace x1 x2 x3 x4 x5) = xdrPut x1 <> (putVarArray 0xffffffff xdrPut) x2 <> (putVarArray 0xffffffff xdrPut) x3 <> xdrPut x4 <> xdrPut x5
  xdrGet = getRecursive (InvocationFrameTrace <$> xdrGet <*> (getVarArray 0xffffffff xdrGet) <*> (getVarArray 0xffffffff xdrGet) <*> xdrGet <*> xdrGet)
  cxsPut (InvocationFrameTrace x1 x2 x3 x4 x5) = cxsPut x1 <> (cxsPutVarArray 0xffffffff cxsPut) x2 <> (cxsPutVarArray 0xffffffff cxsPut) x3 <> cxsPut x4 <> cxsPut x5
  cxsGet = getRecursive (InvocationFrameTrace <$> cxsGet <*> (cxsGetVarArray 0xffffffff cxsGet) <*> (cxsGetVarArray 0xffffffff cxsGet) <*> cxsGet <*> cxsGet)

